import os, pathlib, tempfile
HERE = os.path.dirname(os.path.abspath(__file__)); os.chdir(HERE)
APP = pathlib.Path(HERE).parent.joinpath('inkling.html').as_uri()
import asyncio, json
from playwright.async_api import async_playwright
FAKE = open('test13.py').read().split('FAKE = """')[1].split('"""')[0]
async def sub(pg, top, item):
    await pg.hover('.menu:not(.sub) button:has-text("%s")' % top); await pg.wait_for_timeout(350)
    await pg.click('.menu.sub button:has-text("%s")' % item)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(); pg = await b.new_page(viewport={'width':1440,'height':900}, accept_downloads=True)
        errs=[]; pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.add_init_script(open('mock3d.js').read() + FAKE)
        await pg.goto(APP); await pg.wait_for_timeout(900)
        await pg.click('#newNotebook'); await pg.fill('.modal input.field', 'K'); await pg.keyboard.press('Enter'); await pg.wait_for_timeout(300)
        await (await pg.query_selector_all('.kind'))[2].click(); await pg.fill('.modal input.field', 'Brett'); await pg.click('.modal .btn.primary'); await pg.wait_for_timeout(600)
        await pg.click('#rail button[aria-pressed="true"]'); await pg.wait_for_timeout(200)
        await pg.click('.rtabs button:has-text("Insert")'); await pg.click('#ribbon button[aria-label^="Screen window"]'); await pg.wait_for_timeout(400)
        await pg.click('.obj-scr .scr-empty button:has-text("Choose a tab or window")'); await pg.wait_for_timeout(600)
        win = await pg.query_selector('.obj-scr'); bb = await win.bounding_box()
        await pg.mouse.click(bb['x']+bb['width']*0.75, bb['y']+bb['height']*0.75, button='right'); await pg.wait_for_timeout(200)
        await pg.click('.menu:not(.sub) button:has-text("Add a note with an arrow")'); await pg.wait_for_timeout(250)
        await pg.keyboard.type('Wichtig'); await pg.keyboard.press('Enter'); await pg.wait_for_timeout(300)
        print('note lives in the top layer:', await pg.evaluate("!!document.querySelector('.layer.others .wn-wrap .w3-note') && !document.querySelector('.obj-scr .w3-note')"))
        nb = await (await pg.query_selector('.wn-wrap .w3-note')).bounding_box()
        await pg.mouse.move(nb['x']+20, nb['y']+8); await pg.mouse.down(); await pg.mouse.move(bb['x']+bb['width']+60, nb['y']-40, steps=8); await pg.mouse.up(); await pg.wait_for_timeout(300)
        nb2 = await (await pg.query_selector('.wn-wrap .w3-note')).bounding_box()
        print('note outside the window:', nb2['x'] > bb['x']+bb['width'], '| arrow drawn:', await pg.evaluate("!!document.querySelector('.wn-wrap .w3-arrows line')"))
        gb = await (await pg.query_selector('.wn-wrap .wn-grip')).bounding_box()
        await pg.mouse.move(gb['x']+6, gb['y']+6); await pg.mouse.down(); await pg.mouse.move(gb['x']+106, gb['y']+56, steps=6); await pg.mouse.up(); await pg.wait_for_timeout(300)
        nb3 = await (await pg.query_selector('.wn-wrap .w3-note')).bounding_box()
        print('note resized:', round(nb2['width']), 'x', round(nb2['height']), '->', round(nb3['width']), 'x', round(nb3['height']))
        nm = await (await pg.query_selector('.obj-scr .w3-name')).bounding_box()
        await pg.mouse.move(nm['x']+nm['width']/2, nm['y']+5); await pg.mouse.down(); await pg.mouse.move(nm['x']+nm['width']/2-100, nm['y']+65, steps=6); await pg.mouse.up(); await pg.wait_for_timeout(300)
        nb4 = await (await pg.query_selector('.wn-wrap .w3-note')).bounding_box()
        print('note follows the window:', round(nb4['x']-nb3['x']), round(nb4['y']-nb3['y']))
        await pg.click('#dock button[aria-label="Sticky note (S)"]'); await pg.keyboard.press('Escape'); await pg.wait_for_timeout(200)
        st = await pg.query_selector('.obj-sticky'); sb = await st.bounding_box()
        await pg.mouse.move(sb['x']+30, sb['y']+30); await pg.mouse.down(); await pg.mouse.move(nb4['x']+20, nb4['y']+10, steps=8); await pg.mouse.up(); await pg.wait_for_timeout(200)
        print('note stays in front of a sticky note on top of it:', await pg.evaluate(f"!!document.elementFromPoint({nb4['x']+nb4['width']/2}, {nb4['y']+nb4['height']/2}).closest('.w3-note')"))
        await pg.keyboard.press('Delete'); await pg.mouse.click(1250, 760)
        # instant screenshot window from the Paste chooser
        await pg.click('#dock .dock-caret'); await pg.wait_for_timeout(300)
        print('paste chooser:', await pg.evaluate("[...document.querySelectorAll('.menu:not(.sub) > button,.menu:not(.sub) > .mlabel')].map(b=>b.innerText.trim())"))
        await sub(pg, 'Screen window', 'Screenshot window'); await pg.wait_for_timeout(1500)
        print('after instant screenshot:', await pg.evaluate("[...document.querySelectorAll('.w3-name')].map(n=>n.innerText)"), '| notes copied:', await pg.evaluate("document.querySelectorAll('.wn-wrap .w3-note').length"), '| link:', await pg.evaluate("[...document.querySelectorAll('.connsvg text')].map(t=>t.textContent)"))
        await pg.click('#dock .paste-go'); await pg.wait_for_timeout(1500)
        print('Paste button again:', await pg.evaluate("[...document.querySelectorAll('.w3-name')].map(n=>n.innerText)"), '| button:', await pg.get_attribute('#dock .paste-go', 'title'))
        # new-window option
        await pg.mouse.click(bb['x']-60, bb['y']+bb['height']*0.5+60, button='left')
        w0 = await (await pg.query_selector('.obj-scr')).bounding_box()
        await pg.mouse.click(w0['x']+40, w0['y']+w0['height']*0.5, button='right'); await pg.wait_for_timeout(200)
        await pg.click('.menu button:has-text("Put screenshots and videos in a new window")'); await pg.wait_for_timeout(200)
        await pg.mouse.click(w0['x']+40, w0['y']+w0['height']*0.5, button='right'); await pg.wait_for_timeout(200)
        await pg.click('.menu:not(.sub) button:has-text("Take a screenshot")'); await pg.wait_for_timeout(1500)
        d = await pg.evaluate("(()=>{for(const k of Object.keys(localStorage)) if(k.includes('data:note_')){return Object.values(JSON.parse(localStorage[k]).objs).filter(o=>o.t==='scr'&&!o.del).map(o=>[o.name, o.disp||'live', !!o.newWin])}})()")
        print('windows [name, showing, newWin]:', d)
        # blocks: note box
        await pg.mouse.click(1250, 760)
        await pg.click('#dock button[aria-label="Note box (N)"]'); await pg.keyboard.type('Merke dir das'); await pg.keyboard.press('Escape'); await pg.wait_for_timeout(200)
        n1 = [x for x in await pg.query_selector_all('.obj-note') if 'Merke' in await x.inner_text()][0]; n1b = await n1.bounding_box()
        await pg.mouse.click(n1b['x']+20, n1b['y']+10, button='right'); await pg.wait_for_timeout(200)
        await pg.click('.menu button:has-text("Save as a block")'); await pg.wait_for_timeout(200); await pg.click('.modal .btn.primary'); await pg.wait_for_timeout(500)
        await pg.click('#dock .dock-caret'); await pg.wait_for_timeout(300)
        await pg.click('.menu:not(.sub) button:has-text("Merke dir das")'); await pg.wait_for_timeout(500)
        await pg.click('#dock .paste-go'); await pg.wait_for_timeout(500)
        print('note boxes after pasting the block twice:', await pg.evaluate("[...document.querySelectorAll('.obj-note')].map(n=>n.innerText.trim())"))
        # blocks: selected text on an endless page
        await pg.click('.t-row.top .t-acts button'); await pg.click('.menu button:has-text("New page")'); await pg.wait_for_timeout(200)
        await (await pg.query_selector_all('.kind'))[1].click(); await pg.fill('.modal input.field', 'Text'); await pg.click('.modal .btn.primary'); await pg.wait_for_timeout(500)
        await pg.click('.flow'); await pg.keyboard.type('Die Zelle ist die kleinste Einheit des Lebens.')
        await pg.keyboard.down('Shift');
        for _ in range(18): await pg.keyboard.press('ArrowLeft')
        await pg.keyboard.up('Shift')
        fl = await (await pg.query_selector('.flow')).bounding_box()
        sr = await pg.evaluate("(()=>{const r=getSelection().getRangeAt(0).getBoundingClientRect(); return [r.x+r.width/2, r.y+r.height/2]})()")
        await pg.mouse.click(sr[0], sr[1], button='right'); await pg.wait_for_timeout(250)
        print('text menu:', await pg.evaluate("[...document.querySelectorAll('.menu button,.menu .mlabel')].map(b=>b.innerText.trim())"))
        await pg.click('.menu button:has-text("Save as a block")'); await pg.wait_for_timeout(200); await pg.click('.modal .btn.primary'); await pg.wait_for_timeout(400)
        # page block from the page list
        row = [r for r in await pg.query_selector_all('#tree .t-row') if (await r.inner_text()).strip().startswith('Text')][0]
        await (await row.query_selector('.t-acts button')).click(); await pg.click('.menu button:has-text("Save as a block")'); await pg.wait_for_timeout(200); await pg.click('.modal .btn.primary'); await pg.wait_for_timeout(500)
        await pg.click('#blocksBtn'); await pg.wait_for_timeout(400)
        print('blocks folder:', (await pg.inner_text('.modal')).replace('\n', ' | ')[:330])
        await pg.click('.modal .mrow:has-text("Text") button:has-text("Paste as a new page")'); await pg.wait_for_timeout(1200)
        print('pasted page opened:', await pg.inner_text('#crumbs b'), '| text:', await pg.evaluate("document.querySelector('.flow').innerText.trim()"))
        print('ERRORS', errs[:5])
        await b.close()
asyncio.run(main())
